    @Test
    public void testValidHtml() {
        String bodyHtml = "<html><body>Hello World!</body></html>";
        Whitelist whitelist = Whitelist.none();
        boolean isValid = Jsoup.isValid(bodyHtml, whitelist);
        assertTrue(isValid);
    }

    @Test
    public void testInvalidHtml() {
        String bodyHtml = "<html><body>Hello World!&lt;script>alert('XSS')</script></body></html>";
        Whitelist whitelist = Whitelist.none();
        boolean isValid = Jsoup.isValid(bodyHtml, whitelist);
        assertFalse(isValid);
    }

